<?php require '../config.php';header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['success'=>false]);exit;}$d=json_decode(file_get_contents('php://input'),true)??$_POST;$name=trim($d['name']??'');$email=trim($d['email']??'');$pw=$d['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{8,}$/',$pw)){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Invalid registration details.']);exit;}$q=$conn->prepare('SELECT id FROM users WHERE email=?');$q->bind_param('s',$email);$q->execute();$q->store_result();if($q->num_rows){http_response_code(409);echo json_encode(['success'=>false,'message'=>'Registration could not be completed.']);exit;}$hash=password_hash($pw,PASSWORD_BCRYPT);$q=$conn->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'user')");$q->bind_param('sss',$name,$email,$hash);$ok=$q->execute();http_response_code($ok?201:500);echo json_encode(['success'=>$ok]);
